const rtdal005665Source0002 = `setMethod("rectify", signature(x="Raster"), 
	function(x, ext, res, method='ngb', filename='', ...) {
		stopifnot(rotated(x))
		if ( missing(ext)) {
			ext <- extent(x)
		} else {
			ext <- extent(ext)
		}
		out <- raster(ext)
		if ( missing(res)) {
			res(out) <- abs(raster::res(x))
		} else {
			res(out) <- res
		}
		resample(x, out, method=method, filename=filename, ...)
	}
)`

