const rtdal005681Source0001 = `.setCV <- function(x, v, col) {
	stopifnot(length(v) == (length(col)+1))
	v <- as.numeric(v)
	x@legend@values <- v
	x@legend@color <- col
	x@legend@colortable <- vector()
	x	
}`

const rtdal005681Source0002 = `.setCT <- function(x, v, col, na='white') {
	v <- as.numeric(v)
	na <- which(is.na(v))
	if (length(na)==0) {
		v <- c(NA, v)
		col <- c('white', col)
	} else {
		v <- c(v[na], v[-na])
		col <- c(col[na], col[-na])
	}
	notrgb <- which(substr(col, 1, 1) != '#')
	col[notrgb] <-  grDevices::rgb(t(grDevices::col2rgb(col[notrgb])), maxColorValue=255)
	x@legend@values <- v
	x@legend@color <- col
	x	
}`

