const rtdal005686Source0001 = `setZ <- function(x, z, name='time') {
	if (is.null(z)) {
		x@z <- list()
		return(x)
	}
	if (is.list(z)) {
		z <- unlist(z)
	}
	stopifnot(length(z) == nlayers(x))
	z <- list(z)
	names(z) <- name[1]
	x@z <- z
	x
}`

const rtdal005686Source0002 = `getZ <- function(x) {
	if (length(x@z) == 0) {
		return(NULL)
	} else {
		return(x@z[[1]])
	}
}`

