const rtdal005795Source0004 = `build_package <- function(name, lib_path, tempdir = getwd(),
                          config = character()) {
    file.copy(system.file("tinytest", name, package = "Rcpp"),
              getwd(),
              recursive = TRUE)

    src_path <- file.path(tempdir, name)
    Rcpp::compileAttributes(src_path)
    writeLines(config, file.path(src_path, "src", "config.h"))

    install.packages(
        src_path,
        lib_path,
        repos = NULL,
        type = "source",
        INSTALL_opts = "--install-tests"
    )
}`

