const rtdal005848Source0001 = `Rcpp.plugin.maker <- function(include.before = "",
                              include.after = "",
                              LinkingTo     = unique(c(package, "Rcpp")),
                              Depends       = unique(c(package, "Rcpp")),
                              Imports       = unique(c(package, "Rcpp")),
                              libs          = "",
                              Makevars      = NULL ,
                              Makevars.win  = NULL,
                              package       = "Rcpp") {
    function(...) {
        includes <- sprintf("%s
#include <Rcpp.h>
%s

#ifndef BEGIN_RCPP
#define BEGIN_RCPP
#endif

#ifndef END_RCPP
#define END_RCPP
#endif

using namespace Rcpp;", include.before, include.after)
        out <- list(env = list( PKG_LIBS = libs ),
                    includes = includes,
                    LinkingTo = LinkingTo ,
                    body = function( x ) {
                        sprintf( "BEGIN_RCPP\n%s\nEND_RCPP", x )  # #nocov
                    },
                    Depends = Depends,
                    Imports = Imports)
	if (!is.null(Makevars))     out$Makevars <- Makevars
  	if (!is.null(Makevars.win)) out$Makevars.win <- Makevars.win
  	out
    }
}`

