const rtdal005850Source0001 = `internal_function <- function(pointer){
    f <- function(xp){
        force(xp)
        function(...){
            .External( InternalFunction_invoke, xp, ... )
        }
    }
    o <- new( "C++Function", f(pointer) )
    o@pointer <- pointer
    o
}`

const rtdal005850Source0006 = `setMethod("initialize", "Module",
          function(.Object,
                   moduleName = "UNKNOWN",
                   packageName = "",
                   pointer = .badModulePointer, ...) {
              env <- new.env(TRUE, emptyenv())
              as(.Object, "environment") <- env
              assign("pointer", pointer, envir = env)
              assign("packageName", packageName, envir = env)
              assign("moduleName", moduleName, envir = env)
              if(length(list(...)) > 0) {
                  .Object <- callNextMethod(.Object, ...)       # #nocov
              }
              .Object
          })`

const rtdal005850Source0007 = `.get_Module_function <- function(x, name, pointer = .getModulePointer(x) ){
    pointer <- .getModulePointer(x)
        info <- .Call( Module__get_function, pointer, name )
        fun_ptr <- info[[1L]]
        is_void <- info[[2L]]
        doc     <- info[[3L]]
        sign    <- info[[4L]]
        formal_args <- info[[5L]]
        nargs <- info[[6L]]
        f <- function(...) NULL
        if( nargs == 0L ) formals(f) <- NULL
        stuff <- list( fun_pointer = fun_ptr, InternalFunction_invoke = InternalFunction_invoke )
        body(f) <- if( nargs == 0L ){
            if( is_void ) {
                substitute( {                                   # #nocov start
                    .External( InternalFunction_invoke, fun_pointer)
                    invisible(NULL)
                }, stuff )                                      # #nocov end
            } else {
                substitute( {
                    .External( InternalFunction_invoke, fun_pointer)
                }, stuff )
            }
        } else {
            if( is_void ) {
                substitute( {                                   # #nocov start
                    .External( InternalFunction_invoke, fun_pointer, ... )
                    invisible(NULL)
                }, stuff )                                      # #nocov end
            } else {
                substitute( {
                    .External( InternalFunction_invoke, fun_pointer, ... )
                }, stuff )
            }
        }
        out <- new( "C++Function", f, pointer = fun_ptr, docstring = doc, signature = sign )
        if( ! is.null( formal_args ) ){
            formals( out ) <- formal_args                       # #nocov
        }
        out
}`

const rtdal005850Source0008 = `.get_Module_Class <- function( x, name, pointer =  .getModulePointer(x) ){
    value <- .Call( Module__get_class, pointer, name )
    value@generator <- get("refClassGenerators", envir=x)[[value@.Data]]
    value
}`

const rtdal005850Source0010 = `new_CppObject_xp <- function(module, pointer, ...) {
        .External( class__newInstance, module, pointer, ... )
}`

const rtdal005850Source0011 = `new_dummyObject <- function(...)                                # #nocov
    .External( class__dummyInstance, ...)`

const rtdal005850Source0012 = `cpp_object_initializer <- function(.self, .refClassDef, ..., .object_pointer){
    # force finalize method to be materialized
    invisible(.self$finalize)
    selfEnv <- as.environment(.self)
    ## generate the C++-side object and store its pointer, etc.
    ## access the private fields in the fieldPrototypes env.
    fields <- .refClassDef@fieldPrototypes
    pointer <- if(missing(.object_pointer)) new_CppObject_xp(fields$.module, fields$.pointer, ...) else .object_pointer
    assign(".module", fields$.module, envir = selfEnv)
    assign(".pointer", pointer, envir = selfEnv)
    assign(".cppclass", fields$.pointer, envir = selfEnv)
    .self
}`

const rtdal005850Source0015 = "Module <- function( module, PACKAGE = methods::getPackageName(where), where = topenv(parent.frame()), mustStart = FALSE ) {\n    if (inherits(module, \"DLLInfo\") && missing(mustStart)) mustStart <- TRUE\t\t\t\t\t\t# #nocov\n    if (inherits(module, \"Module\")) {\n        xp <- .getModulePointer(module, FALSE)\n        if(!missing(PACKAGE))\n            warning(\"ignoring PACKAGE argument in favor of internal package from Module object\")\t# #nocov\n        env <- as.environment(module) # not needed from R 2.12.0\n        PACKAGE <- get(\"packageName\", envir = env)\n        moduleName <- get(\"moduleName\", envir = env)\n    }\n    else if( identical( typeof( module ), \"externalptr\" ) ){\n        ## [john] Should Module() ever be called with a pointer as argument?\n        ## If so, we need a safe check of the pointer's validity\n\n        ## [romain] I don't think we actually can, external pointers\n        ## are stored as void*, they don't know what they are. Or we could\n        ## perhaps keep a vector of all known module pointers\n        ## [John]  One technique is to initialize the pointer to a known value\n        ## and just check whether it's been reset from that (bad) value\n        xp <- module                                            # #nocov start\n        moduleName <- .Call( Module__name, xp )\n        module <- methods::new(\"Module\", pointer = xp, packageName = PACKAGE,\n                      moduleName = moduleName)                  # #nocov end\n    } else if(is.character(module)) {\n        moduleName <- module\n        xp <- .badModulePointer\n        module <- methods::new(\"Module\", pointer = xp, packageName = PACKAGE,\n                      moduleName = moduleName)\n    }\n    if(identical(xp, .badModulePointer)) {\n        if(mustStart) {\n            name <- sprintf( \"_rcpp_module_boot_%s\", moduleName )\n            symbol <- tryCatch(getNativeSymbolInfo( name, PACKAGE ),\n                               error = function(e)e)\n            if(inherits(symbol, \"error\"))\n                stop(gettextf(\"Failed to initialize module pointer: %s\",\n                              symbol), domain = NA)\n            xp  <- .Call( symbol )\n            .setModulePointer(module, xp)\n        }\n        else\n            return(module)\n    }\n    classes <- .Call( Module__classes_info, xp )\n\n    ## We need a general strategy for assigning class defintions\n    ## since delaying the initialization of the module causes\n    ## where to be the Rcpp namespace:\n    if(environmentIsLocked(where))\n        where <- .GlobalEnv # or???\n    generators <- list()\n\n    storage <- new.env()\n\n    for( i in seq_along(classes) ){\n        CLASS <- classes[[i]]\n\n        clname <- CLASS@.Data\n\n        fields <- cpp_fields( CLASS, where )\n        methods <- cpp_refMethods(CLASS, where)\n        generator <- methods::setRefClass( clname,\n                                 fields = fields,\n                                 contains = \"C++Object\",\n                                 methods = methods,\n                                 where = where\n                                 )\n        # just to make codetools happy\n        .self <- .refClassDef <- NULL\n        generator$methods(initialize =\n              if (cpp_hasDefaultConstructor(CLASS))\n                 function(...) Rcpp::cpp_object_initializer(.self,.refClassDef, ...)\n              else\n                 function(...) {\n                     if (nargs()) Rcpp::cpp_object_initializer(.self,.refClassDef, ...)\n                     else Rcpp::cpp_object_dummy(.self, .refClassDef) \t\t\t# #nocov\n                 }\n                          )\n        rm( .self, .refClassDef )\n\n        classDef <- methods::getClass(clname)\n        ## non-public (static) fields in class representation\n        ## <fixme>  Should these become real fields? </fixme>\n        fields <- classDef@fieldPrototypes\n        assign(\".pointer\", CLASS@pointer, envir = fields)\n        assign(\".module\", xp, envir = fields)\n        assign(\".CppClassName\", clname, envir = fields)\n        generators[[clname]] <- generator\n\n        # [romain] : should this be promoted to reference classes\n        #            perhaps with better handling of j and ... arguments\n        if( any( grepl( \"^[[]\", names(CLASS@methods) ) ) ){             # #nocov start\n            if( \"[[\" %in% names( CLASS@methods ) ){\n                methods::setMethod( \"[[\", clname, function(x, i, j, ..., exact = TRUE){\n                    x$`[[`( i )\n                }, where = where )\n            }\n\n            if( \"[[<-\" %in% names( CLASS@methods ) ){\n                methods::setReplaceMethod( \"[[\", clname, function(x, i, j, ..., exact = TRUE, value){\n                    x$`[[<-`( i, value )\n                    x\n                } , where = where )\n            }\n        }                                                               # #nocov end\n\n        # promoting show to S4\n        if( any( grepl( \"show\", names(CLASS@methods) ) ) ){\n            setMethod( \"show\", clname, function(object) object$show(), where = where )  # #nocov\n        }\n\n    }\n    if(length(classes)) {\n        module$refClassGenerators <- generators\n    }\n\n    for( i in seq_along(classes) ){\n        CLASS <- classes[[i]]\n        clname <- CLASS@.Data\n        demangled_name <- sub( \"^Rcpp_\", \"\", clname )\n        .classes_map[[ CLASS@typeid ]] <- storage[[ demangled_name ]] <- .get_Module_Class( module, demangled_name, xp )\n\n        # exposing enums values as CLASS.VALUE\n        # (should really be CLASS$value but I don't know how to do it)\n        if( length( CLASS@enums ) ){\n            for( enum in CLASS@enums ){                                         # #nocov start\n                for( i in 1:length(enum) ){\n                    storage[[ paste( demangled_name, \".\", names(enum)[i], sep = \"\" ) ]] <- enum[i]\n                }\n            }                                                                   # #nocov end\n        }\n\n    }\n\n    # functions\n    functions <- .Call( Module__functions_names, xp )\n    for( fun in functions ){\n        storage[[ fun ]] <- .get_Module_function( module, fun, xp )\n\n        # register as(FROM, TO) methods\n        converter_rx <- \"^[.]___converter___(.*)___(.*)$\"\n        if( length( matches <- grep( converter_rx, functions ) ) ){             # #nocov start\n            for( i in matches ){\n                fun <- functions[i]\n                from <- sub( converter_rx, \"\\\\1\", fun )\n                to   <- sub( converter_rx, \"\\\\2\", fun )\n                converter <- function( from ){}\n                body( converter ) <- substitute( { CONVERT(from) },\n                    list( CONVERT = storage[[fun]] )\n                )\n                setAs( from, to, converter, where = where )\n            }\n        }                                                                       # #nocov end\n\n    }\n\n    assign( \"storage\", storage, envir = as.environment(module) )\n    module\n}"

const rtdal005850Source0017 = `method_wrapper <- function( METHOD, where ){
        noargs <- all( METHOD$nargs == 0 )
        stuff <- list(
            class_pointer = METHOD$class_pointer,
            pointer = METHOD$pointer,
            CppMethod__invoke = CppMethod__invoke,
            CppMethod__invoke_void = CppMethod__invoke_void,
            CppMethod__invoke_notvoid = CppMethod__invoke_notvoid,
            dealWith = dealWith,
            docstring = METHOD$info("")
        )
        f <- function(...) NULL
        if( noargs ){
            formals(f) <- NULL
        }

        extCall <- if( noargs ) {
            if( all( METHOD$void ) ){
                # all methods are void, so we know we want to return invisible(NULL)
                substitute(
                {
                    docstring
                    .External(CppMethod__invoke_void, class_pointer, pointer, .pointer )
                    invisible(NULL)
                } , stuff )
            } else if( all( ! METHOD$void ) ){
                # none of the methods are void so we always return the result of
                # .External
                substitute(
                {
                    docstring
                   .External(CppMethod__invoke_notvoid, class_pointer, pointer, .pointer )
                } , stuff )
            } else {
                # some are void, some are not, so the voidness is part of the result
                # we get from internally and we need to deal with it
                substitute(                                                     # #nocov start
                    {
                        docstring
                        dealWith( .External(CppMethod__invoke, class_pointer, pointer, .pointer ) )
                } , stuff )                                                     # #nocov end
            }
        } else {
            if( all( METHOD$void ) ){
                # all methods are void, so we know we want to return invisible(NULL)
                substitute(
                {
                    docstring
                    .External(CppMethod__invoke_void, class_pointer, pointer, .pointer, ...)
                    invisible(NULL)
                } , stuff )
            } else if( all( ! METHOD$void ) ){
                # none of the methods are void so we always return the result of
                # .External
                substitute(
                {
                    docstring
                   .External(CppMethod__invoke_notvoid, class_pointer, pointer, .pointer, ...)
                } , stuff )
            } else {
                # some are void, some are not, so the voidness is part of the result
                # we get from internally and we need to deal with it
                substitute(                                                     # #nocov start
                    {
                        docstring
                        dealWith( .External(CppMethod__invoke, class_pointer, pointer, .pointer, ...) )
                } , stuff )                                                     # #nocov end
            }
        }
        body(f, where) <- extCall
        f
        }`

const rtdal005850Source0020 = `binding_maker <- function( FIELD, where ){
    f <- function( x ) NULL
    body(f) <- substitute({
        if( missing( x ) )
            .Call( CppField__get, class_pointer, pointer, .pointer)
        else
            .Call( CppField__set, class_pointer, pointer, .pointer, x)
    }, list(class_pointer = FIELD$class_pointer,
            pointer = FIELD$pointer,
            CppField__get = CppField__get,
            CppField__set = CppField__set ))
    environment(f) <- where
    f
}`

